     1→/**
     2→ * FreeLang CLI - Command Line Interface
     3→ * Usage: freelang <command> [options]
     4→ */
     5→
     6→import * as path from 'path';
     7→import { ProgramRunner } from './runner';
     8→import { compileAOT } from './aot-compiler';
     9→import { ProofTester } from './test-runner';
    10→
    11→interface CLIOptions {
    12→  verbose?: boolean;
    13→  showIR?: boolean;
    14→  debug?: boolean;
    15→  aot?: boolean;        // Phase 5: AOT compilation
    16→  output?: string;      // Phase 5: Output binary path
    17→  test?: boolean;       // Self-Testing Compiler: --test 플래그
    18→  pattern?: string;     // --pattern 테스트 파일 필터
    19→}
    20→
    21→export class FreeLangCLI {
    22→  private runner: ProgramRunner;
    23→
    24→  constructor() {
    25→    this.runner = new ProgramRunner();
    26→  }
    27→
    28→  /**
    29→   * Parse command line arguments
    30→   */
    31→  private parseArgs(args: string[]): {
    32→    command: string;
    33→    file?: string;
    34→    options: CLIOptions;
    35→  } {
    36→    const command = args[0];
    37→    const restArgs = args.slice(1);
    38→    const options: CLIOptions = {};
    39→
    40→    let file: string | undefined;
    41→
    42→    for (let i = 0; i < restArgs.length; i++) {
    43→      const arg = restArgs[i];
    44→      if (arg === '--verbose' || arg === '-v') {
    45→        options.verbose = true;
    46→      } else if (arg === '--show-ir') {
    47→        options.showIR = true;
    48→      } else if (arg === '--debug') {
    49→        options.debug = true;
    50→      } else if (arg === '--aot') {
    51→        options.aot = true;
    52→      } else if (arg === '-o' || arg === '--output') {
    53→        options.output = restArgs[++i];  // Next arg is the output path
    54→      } else if (arg === '--test') {
    55→        options.test = true;
    56→      } else if (arg === '--pattern' || arg === '-p') {
    57→        options.pattern = restArgs[++i];
    58→      } else if (!arg.startsWith('-')) {
    59→        file = arg;
    60→      }
    61→    }
    62→
    63→    return { command, file, options };
    64→  }
    65→
    66→  /**
    67→   * Print help message
    68→   */
    69→  private printHelp(): void {
    70→    console.log(`
